<article class="card product-card">
<?php if($gallery):?><div class="product-gallery" data-gallery="<?=e(json_encode($gallery,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT))?>"><button class="gallery-open" type="button" aria-label="Enlarge photos of <?=e($p['name'])?>"><img class="gallery-main" src="<?=e($gallery[0]['thumbnail_url']??$gallery[0]['url'])?>" alt="<?=e($p['name'])?>" loading="lazy"><span>View photos ⤢</span></button><div class="gallery-thumbs"><?php foreach($gallery as $i=>$photo):?><button type="button" class="gallery-thumb <?= $i===0?'selected':'' ?>" data-index="<?=$i?>" aria-label="View image <?=$i+1?>"><img src="<?=e($photo['thumbnail_url']??$photo['url'])?>" alt="" loading="lazy"></button><?php endforeach;?></div></div><?php endif;?>
