<?php if((int)$p['quantity']>0):?><form method="post" action="/cart.php" class="add-cart"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?=(int)$p['productId']?>"><label>Qty <input type="number" name="quantity" min="1" max="<?=(int)$p['quantity']?>" value="1" required></label><button>Add to cart</button></form><?php else:?><p>Not currently stocked</p><?php endif;?></article><?php endforeach;?></div><?php if(!$products):?><p>No rental products yet.</p><?php endif;?>
